import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";
import ControlsExample from "./variants/controls";
const ControlsSource = "import { Button } from "@/registry/erbium/ui/button";
import { Input } from "@/registry/erbium/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/erbium/ui/select";
import { Toggle } from "@/registry/erbium/ui/toggle";
import { Tabs, TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";

export default function ControlsExample() {
  return (
    <div className="flex flex-col gap-section p-panel">
      <div className="flex flex-wrap items-center gap-related">
        <Button size="xs">Embedded</Button>
        <Button size="sm">Small</Button>
        <Button>Default</Button>
        <Button size="lg">Large</Button>
      </div>
      <div className="flex flex-wrap items-center gap-related">
        <Input aria-label="Search projects" placeholder="Search projects" className="w-48" />
        <Select defaultValue="updated">
          <SelectTrigger>
            <SelectValue>
              {(value) => (value === "updated" ? "Recently updated" : "Project name")}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="updated">Recently updated</SelectItem>
            <SelectItem value="name">Project name</SelectItem>
          </SelectContent>
        </Select>
        <Toggle aria-label="Pin projects">Pin</Toggle>
        <Button>New project</Button>
      </div>
      <Tabs defaultValue="table">
        <TabsList>
          <TabsTrigger value="table">Table</TabsTrigger>
          <TabsTrigger value="board">Board</TabsTrigger>
        </TabsList>
      </Tabs>
      <div lang="fa" dir="rtl" className="flex flex-wrap items-center gap-related">
        <Input aria-label="جستجو" placeholder="جستجوی پروژه‌ها" className="w-48" />
        <Button>پروژه جدید</Button>
      </div>
      <p className="text-caption text-muted-foreground">
        Resize the container and use touch emulation: layout wraps, editable text stays readable,
        and general targets expand.
      </p>
    </div>
  );
}
";
import CompositionExample from "./variants/composition";
const CompositionSource = "import { Button } from "@/registry/erbium/ui/button";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/registry/erbium/ui/card";
import { Input } from "@/registry/erbium/ui/input";
import { Field, FieldLabel, FieldGroup } from "@/registry/erbium/ui/field";

export default function CompositionExample() {
  return (
    <div className="grid gap-section p-panel sm:grid-cols-2">
      {(["default", "sm"] as const).map((size) => (
        <Card key={size} size={size}>
          <CardHeader>
            <CardTitle>Project settings</CardTitle>
            <CardDescription>
              Panel size changes spacing, while text retains its role.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <FieldGroup>
              <Field>
                <FieldLabel>Project name</FieldLabel>
                <Input defaultValue="Erbium" />
              </Field>
              <Field>
                <FieldLabel>Team</FieldLabel>
                <Input defaultValue="Design systems" />
              </Field>
            </FieldGroup>
          </CardContent>
          <CardFooter className="flex-wrap justify-end gap-related">
            <Button variant="ghost">Cancel</Button>
            <Button>Save changes</Button>
          </CardFooter>
        </Card>
      ))}
    </div>
  );
}
";
const meta = {
  parameters: {
    docs: { description: { component: "Erbium uses Mira's compact proportions, coordinated with shared typography and surface roles. Sizes are CSS defaults; no density provider or sizing hook is required. See the [sizing guide](/docs/sizing) for the decisions and responsive behavior." } },
    layout: "fullscreen",
  },
} satisfies Meta;
export default { ...meta, title: "Foundations/Sizing",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;
type Story = StoryObj;
export const Controls: Story = {
  parameters: {
    docs: {
      description: { story: "Compare related controls together. Default controls use a 28px minimum, compact controls 24px, and large controls 32px. Below 48rem general controls use a 36px minimum to align with readable fields. Touch targets expand independently of viewport width." },
      source: { code: ControlsSource },
    },
  },
  render: ControlsExample,
};
export const Composition: Story = {
  parameters: {
    docs: {
      description: { story: "Panel insets, field groups, and related actions form a consistent hierarchy. Narrow containers wrap actions without shrinking reading text." },
      source: { code: CompositionSource },
    },
  },
  render: CompositionExample,
};

